import type { LucideIcon } from "lucide-react";
import {
  Activity,
  Blend,
  Contrast,
  Droplets,
  Eraser,
  Expand,
  Eye,
  Layers,
  LogIn,
  LogOut,
  MoveRight,
  RefreshCw,
  Sparkles,
  Star,
  Sun,
  Type,
  Wand2,
  Zap,
} from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";
import { FX_CATEGORY_LABELS, fxEntries, fxEntry, missingCapabilities } from "@/lib/fx/manifest";

/** Real filter thumbnails — generated by the production ffmpeg pipeline
    (qa/fx-thumb test writes shared/fx/thumbs/<id>.png; the glob keeps them
    out of the bundle when absent). */
const THUMBS = import.meta.glob("../../../shared/fx/thumbs/*.png", { eager: true, query: "?url", import: "default" }) as Record<string, string>;
const thumbUrl = (id: string) => THUMBS[`../../../shared/fx/thumbs/${id}.png`];
import { setDragPayload, type EffectCategory } from "@/lib/drag-payload";
import { EFFECTS } from "@/lib/effects";
import { ANIM_PRESETS } from "@/lib/anim-presets";
import { COMBO_PRESETS, comboPreset } from "@/lib/fx-combos";

/**
 * Effects library — draggable tiles applied to timeline clips on drop.
 *
 * Every tile maps to a render-supported primitive, so preview ≈ export:
 *  - start/end  → animation presets (baked transform/opacity keyframes or
 *                 textFx for text/graphics clips), ADR-027
 *  - merge      → track.transitions (ffmpeg xfade)
 *  - overlay    → clip.effects entries (CSS / SVG-matrix + ffmpeg parity)
 */

interface FxItem {
  id: string;
  label: string;
  icon: LucideIcon;
  /** i18n description key under editor.fxDesc.* — optional. */
  descKey?: string;
  /** Library description (manifest) shown as tooltip. */
  description?: string;
  /** Animated-thumbnail CSS class (index.css). */
  thumb?: string;
  /** Photographic thumbnail URL (production-pipeline render). */
  thumbImg?: string;
  /** Animated 8-frame sprite strip (production-pipeline render). */
  stripImg?: string;
}

/** CSS thumb class per anim preset — a card performing the gesture
    (index.css `.fxa-*`), so icon-less presets show their motion. */
const PRESET_THUMBS: Record<string, string> = {
  fadeIn: "fxa-fadeIn",
  scaleIn: "fxa-scaleIn",
  bounceIn: "fxa-bounceIn",
  spinIn: "fxa-spinIn",
  slideIn: "fxa-slideIn",
  typewriter: "fxa-typewriter",
  wipe: "fxa-wipe",
  fadeOut: "fxa-fadeOut",
  typewriterOut: "fxa-typewriterOut",
  wipeOut: "fxa-wipeOut",
  zoomPunch: "fxa-zoomPunch",
};

const preset = (id: string, icon: LucideIcon): FxItem => ({
  id,
  icon,
  label: ANIM_PRESETS.find((p) => p.id === id)?.label ?? id,
  thumb: PRESET_THUMBS[id],
});

const OVERLAY_ICONS: Record<string, LucideIcon> = {
  brightness: Sun,
  contrast: Contrast,
  saturation: Sparkles,
  blur: Droplets,
};

/** Basic per-clip color controls — legacy effectDef types that belong in
    the Grade tab next to the looks, not under VFX. */
const ADJUST_IDS = new Set(["brightness", "contrast", "saturation", "blur"]);

/** Phase E signature picks — the tiles a creator would choose Creatora
    for. Marked in the bin; kept honest by the catalog audit. */
const SIGNATURE = new Set(["signalOff", "disintegrate", "inkBleed", "velocitySwipe"]);

/** Top-level bin tabs — one axis per tab so the 15-way chip soup becomes
    three focused shelves. Groups keep `id` for drop routing; `tab` only
    controls presentation. */
export type FxTab = "grade" | "animate" | "transitions";

/** Exported so the fx-catalog audit test iterates the same tiles the UI
    renders — a tile that maps to nothing is a test failure, not a silent
    no-op. */
export const FX_CATALOG: { id: EffectCategory; labelKey: string; icon: LucideIcon; tab: FxTab; items: FxItem[] }[] = [
  {
    id: "overlay",
    labelKey: "editor.fxCatFilters",
    icon: Sparkles,
    tab: "grade",
    items: fxEntries()
      .filter((e) => e.kind === "filter")
      .map((e) => ({
        id: e.id,
        label: e.name,
        icon: Sparkles,
        description: e.description,
        thumbImg: thumbUrl(e.id),
      })),
  },
  {
    id: "overlay",
    labelKey: "editor.fxCatAdjust",
    icon: Contrast,
    tab: "grade",
    items: EFFECTS.filter((e) => ADJUST_IDS.has(e.type)).map((e) => ({
      id: e.type,
      label: e.label,
      icon: OVERLAY_ICONS[e.type] ?? Contrast,
      description: fxEntry(e.type)?.description,
      thumbImg: thumbUrl(e.type),
    })),
  },
  {
    id: "overlay",
    labelKey: "editor.fxCatLight",
    icon: Sun,
    tab: "grade",
    items: fxEntries()
      .filter((e) => e.kind === "effect" && e.category === "light")
      .map((e) => ({
        id: e.id,
        label: e.name,
        icon: Sun,
        description: e.description,
        stripImg: thumbUrl(e.id),
      })),
  },
  {
    id: "start",
    labelKey: "editor.fxCatStart",
    icon: LogIn,
    tab: "animate",
    items: [
      ...fxEntries()
        .filter((e) => e.kind === "effect" && e.category === "intro")
        .map((e) => ({ id: e.id, label: e.name, icon: LogIn, description: e.description, thumb: e.thumb, stripImg: thumbUrl(e.id) })),
      preset("fadeIn", Eye),
      preset("scaleIn", Expand),
      preset("bounceIn", Activity),
      preset("spinIn", RefreshCw),
      preset("slideIn", MoveRight),
      preset("typewriter", Type),
      preset("wipe", Eraser),
    ],
  },
  {
    id: "end",
    labelKey: "editor.fxCatEnd",
    icon: LogOut,
    tab: "animate",
    items: [
      ...fxEntries()
        .filter((e) => e.kind === "effect" && e.category === "outro")
        .map((e) => ({ id: e.id, label: e.name, icon: LogOut, description: e.description, thumb: e.thumb, stripImg: thumbUrl(e.id) })),
      preset("fadeOut", Eye),
      preset("typewriterOut", Type),
      preset("wipeOut", Eraser),
    ],
  },
  {
    id: "merge",
    labelKey: "editor.fxCatMerge",
    icon: Blend,
    tab: "transitions",
    items: [
      ...fxEntries()
        .filter((e) => e.kind === "transition")
        .map((e) => ({ id: e.id, label: e.name, icon: Zap, description: e.description, thumb: e.thumb, stripImg: thumbUrl(e.id) })),
      // Former legacy xfades are manifest entries now (same ids — old
      // projects upgrade); other native xfades still render in old
      // projects via plan.rs but are not offered as new tiles.
    ],
  },
  {
    id: "overlay",
    labelKey: "editor.fxCatCombos",
    icon: Layers,
    tab: "animate",
    items: COMBO_PRESETS.map((c) => ({
      id: c.id,
      label: c.label,
      icon: Layers,
      description: c.description,
      thumb: c.thumb,
    })),
  },
  {
    id: "overlay",
    labelKey: "editor.fxCatOverlay",
    icon: Wand2,
    tab: "animate",
    items: [
      ...EFFECTS.filter(
        (e) =>
          !ADJUST_IDS.has(e.type) &&
          !["light", "intro", "outro"].includes(fxEntry(e.type)?.category ?? ""),
      ).map((e) => ({
        id: e.type,
        label: e.label,
        icon: OVERLAY_ICONS[e.type] ?? Wand2,
        description: fxEntry(e.type)?.description,
        thumb: fxEntry(e.type)?.thumb,
      })),
      // Emphasis animation presets — the drop handler routes any
      // ANIM_PRESETS id to the keyframe path regardless of category.
      preset("zoomPunch", Zap),
    ],
  },
];

/** Display section (the 8 library categories) for a catalog item. */
function sectionOf(cat: EffectCategory, id: string): string {
  if (comboPreset(id)) return "combos";
  const e = fxEntry(id);
  if (e) return e.category;
  if (cat === "merge") return "classic";
  if (cat === "start") return "intro";
  if (cat === "end") return "outro";
  if (ADJUST_IDS.has(id)) return "adjust";
  return ["pulse", "shake", "zoomPunch"].includes(id) ? "motion" : "vfx";
}

const FX_TABS: { id: FxTab; labelKey: string }[] = [
  { id: "grade", labelKey: "editor.fxTabGrade" },
  { id: "animate", labelKey: "editor.fxTabAnimate" },
  { id: "transitions", labelKey: "editor.fxTabTransitions" },
];

export function EffectsBin() {
  const { t } = useTranslation();
  const [tab, setTab] = useState<FxTab>("grade");
  const [section, setSection] = useState<string>("all");
  const groups = FX_CATALOG.filter((c) => c.tab === tab);
  const sections = Array.from(
    new Set(groups.flatMap((c) => c.items.map((i) => sectionOf(c.id, i.id)))),
  );
  const [showAll] = [section === "all"];
  return (
    <div className="flex h-full flex-col overflow-y-auto">
      <div className="flex gap-1 border-b border-border/60 px-2 pt-1.5">
        {FX_TABS.map((tb) => (
          <button
            key={tb.id}
            onClick={() => {
              setTab(tb.id);
              setSection("all");
            }}
            className={`flex-1 rounded-t-md border-b-2 px-2 py-1 text-[11px] font-medium transition-colors ${
              tab === tb.id
                ? "border-primary bg-primary/10 text-foreground"
                : "border-transparent text-muted-foreground hover:bg-accent hover:text-foreground"
            }`}
          >
            {t(tb.labelKey)}
          </button>
        ))}
      </div>
      <div className="flex flex-wrap gap-1 border-b border-border/60 px-2 py-1.5">
        {["all", ...sections].map((s2) => (
          <button
            key={s2}
            onClick={() => setSection(s2)}
            className={`rounded-full border px-2 py-0.5 text-[10px] ${section === s2 ? "border-primary bg-primary/15 text-foreground" : "border-border text-muted-foreground hover:bg-accent"}`}
          >
            {s2 === "all"
              ? "All"
              : (FX_CATEGORY_LABELS[s2] ??
                s2.replace(/[-_]/g, " ").replace(/\b\w/g, (ch) => ch.toUpperCase()))}
          </button>
        ))}
      </div>
      {groups.map((cat) => {
        const items = cat.items
          .filter((i) => showAll || sectionOf(cat.id, i.id) === section)
          .sort((a, b) => Number(SIGNATURE.has(b.id)) - Number(SIGNATURE.has(a.id)));
        if (!items.length) return null;
        return (
          <div key={cat.labelKey} className="border-b border-border/60">
            <div className="flex items-center gap-1.5 px-2.5 py-1.5 text-[10px] font-medium uppercase tracking-wide text-muted-foreground">
              <cat.icon className="size-3" />
              {t(cat.labelKey)}
            </div>
            <div className="grid grid-cols-2 gap-1 px-2 pb-2">
              {items.map((item) => {
                const lacks = fxEntry(item.id) ? missingCapabilities(fxEntry(item.id)!) : [];
                return (
                  <div
                    key={item.id}
                    draggable={!lacks.length}
                    title={item.description ?? t("editor.fxDragHint")}
                    onDragStart={(e) => {
                      e.dataTransfer.setData(
                        "application/x-creatora-effect",
                        JSON.stringify({ category: cat.id, itemId: item.id }),
                      );
                      e.dataTransfer.effectAllowed = "copy";
                      setDragPayload({ effect: true, category: cat.id, itemId: item.id });
                    }}
                    onDragEnd={() => setDragPayload(null)}
                    className={`group relative flex cursor-grab flex-col gap-1 rounded border border-border bg-background/60 px-1.5 py-1.5 text-[11px] hover:border-primary/50 hover:bg-accent active:cursor-grabbing ${lacks.length ? "opacity-50" : ""}`}
                  >
                    {item.thumbImg && (
                      <img src={item.thumbImg} alt="" className="h-12 w-full rounded-sm object-cover" draggable={false} />
                    )}
                    {item.stripImg && !item.thumbImg && (
                      <div
                        className="fxstrip h-12 w-full rounded-sm"
                        style={{ backgroundImage: `url(${item.stripImg})` }}
                        aria-hidden
                      />
                    )}
                    {item.thumb && !item.thumbImg && !item.stripImg && (
                      <div className={`fxt ${item.thumb}`} aria-hidden />
                    )}
                    {!item.thumbImg && !item.stripImg && !item.thumb && (
                      <div className="flex h-12 w-full items-center justify-center rounded-sm bg-accent/40">
                        <item.icon className="size-5 text-muted-foreground/60" />
                      </div>
                    )}
                    {SIGNATURE.has(item.id) && (
                      <span
                        title="Signature"
                        className="absolute left-1 top-1 rounded bg-black/60 px-1 py-0.5 text-amber-300"
                      >
                        <Star className="size-2.5 fill-amber-300" />
                      </span>
                    )}
                    <div className="flex items-center gap-1.5">
                      <item.icon className="size-3.5 shrink-0 text-muted-foreground" />
                      <span className="truncate">{item.label}</span>
                    </div>
                    <button
                      disabled={!!lacks.length}
                      title={lacks.length ? `Needs: ${lacks.join(", ")}` : "Apply to the selected clip"}
                      onClick={() =>
                        window.dispatchEvent(
                          new CustomEvent("creatora:apply-fx", { detail: { category: cat.id, itemId: item.id } }),
                        )
                      }
                      className="absolute right-1 top-1 hidden rounded bg-primary px-1.5 py-0.5 text-[10px] text-primary-foreground group-hover:block"
                    >
                      Apply
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}
      <p className="px-2.5 py-2 text-[10px] leading-snug text-muted-foreground/70">
        {t("editor.fxBinFooter")}
      </p>
    </div>
  );
}
